import { useEffect, useState, type FormEvent } from 'react'
import { BrowserRouter, Navigate, Route, Routes, useNavigate, useLocation } from 'react-router-dom'
import { api } from './services/api'
import { LayoutDashboard, FileText, WalletCards, Users, Building2, BarChart3, ShieldAlert, ClipboardCheck, Bell, Moon, Sun, LogOut, Search, Plus, Upload, X, CheckCircle, XCircle, Eye } from 'lucide-react'
import { ResponsiveContainer, BarChart, Bar, XAxis, YAxis, Tooltip, CartesianGrid, PieChart, Pie, Cell } from 'recharts'

type Claim={id:number;claim_id:string;customer:string;type:string;amount:number;status:string;risk_score:number;risk_category:string;created_at:string}

function BrandMark({small=false}:{small?:boolean}){
	return <div className={small?'brand-mark brand-mark-small':'brand-mark'} aria-label="Drishti">
		<svg viewBox="0 0 64 64" aria-hidden="true">
			<path d="M8 32c7-9 15-14 24-14s17 5 24 14c-7 9-15 14-24 14S15 41 8 32Z" fill="none" stroke="currentColor" strokeWidth="4" strokeLinecap="round" strokeLinejoin="round"/>
			<circle cx="32" cy="32" r="8" fill="none" stroke="currentColor" strokeWidth="4"/>
			<circle cx="32" cy="32" r="3" fill="currentColor"/>
			<path d="M43 40v9c-3 4-7 7-11 9-4-2-8-5-11-9v-9" fill="none" stroke="currentColor" strokeWidth="4" strokeLinecap="round" strokeLinejoin="round"/>
		</svg>
	</div>
}

function Login(){const nav=useNavigate();const [email,setEmail]=useState('investigator@demo.com');const [password,setPassword]=useState('Demo@123');const [demoRole,setDemoRole]=useState('Investigator');const [error,setError]=useState('');
async function submit(e:FormEvent){e.preventDefault();setError('');try{const {data}=await api.post('/auth/login',{email,password});localStorage.setItem('token',data.access_token);localStorage.setItem('user',JSON.stringify(data.user));nav(data.user.role==='Customer'?'/customer':data.user.role==='Admin'?'/admin':'/investigator')}catch{setError('Sign-in failed. Verify PostgreSQL and the backend are running.')}}
function scrollToLogin(){document.getElementById('secure-login')?.scrollIntoView({behavior:'smooth',block:'center'})}
useEffect(()=>{
		const page=document.querySelector('.landing-page') as HTMLElement|null;
		if(!page)return;
		const targets=page.querySelectorAll('.section-heading,.feature-grid article,.signal-panel,.intelligence-copy,.landing-footer');
		targets.forEach(target=>target.classList.add('scroll-reveal'));
		const observer=new IntersectionObserver(entries=>{entries.forEach(entry=>{if(entry.isIntersecting)entry.target.classList.add('revealed')})},{threshold:.14,rootMargin:'0px 0px -8% 0px'});
		targets.forEach(target=>observer.observe(target));
		const update=()=>{const max=page.scrollHeight-window.innerHeight;page.style.setProperty('--scroll-progress',max>0?`${Math.min(1,window.scrollY/max)}`:'0')};
		window.addEventListener('scroll',update,{passive:true});update();
		return()=>{observer.disconnect();window.removeEventListener('scroll',update)};
	},[]);
return <div className="landing-page" onMouseMove={e=>{const rect=e.currentTarget.getBoundingClientRect();e.currentTarget.style.setProperty('--cursor-x',`${e.clientX-rect.left}px`);e.currentTarget.style.setProperty('--cursor-y',`${e.clientY-rect.top}px`)}}>
	<div className="cursor-light" aria-hidden="true"/>
	<header className="landing-nav">
		<a className="landing-brand" href="#top"><BrandMark small/><span><strong>DRISHTI</strong><small>INSURANCE INTELLIGENCE</small></span></a>
		<nav><a className="active" href="#top">Overview</a><a href="#platform">Platform</a><a href="#intelligence">Intelligence</a><a href="#security">Security</a></nav>
		<div className="nav-actions"><span className="nav-status"><i/> SYSTEM ONLINE</span><button className="nav-login" onClick={scrollToLogin}>Workspace <span>↗</span></button></div>
	</header>
	<main id="top">
		<section className="hero-section">
			<div className="hero-grid" aria-hidden="true"/><div className="hero-glow" aria-hidden="true"/>
			<div className="hero-copy"><div className="hero-brand-name">DRISHTI</div><div className="hero-label"><span/> INSURANCE INTELLIGENCE SYSTEM</div><h1>One clear view.<br/><em>Every claim.</em></h1><p>Drishti turns complex insurance evidence into decisive, explainable action — in real time.</p><div className="hero-actions"><button className="hero-primary" onClick={scrollToLogin}>Enter workspace <span>→</span></button><a className="hero-secondary" href="#platform"><span>Explore platform</span><b>↓</b></a></div><div className="hero-proof"><div><strong>99.2%</strong><span>Detection confidence</span></div><div><strong>&lt;60s</strong><span>Risk assessment</span></div><div><strong>24×7</strong><span>Continuous watch</span></div></div></div>
			<div className="hero-stage" id="secure-login"><div className="orbit orbit-a"/><div className="orbit orbit-b"/><div className="vision-mark"><div className="vision-eye"><Eye/><i/></div></div>
				<form className="hero-login-card" onSubmit={submit}><div className="login-card-head"><div><span>PRIVATE WORKSPACE</span><h2>Good to see you.</h2></div><BrandMark small/></div><label><span>Email address</span><input value={email} onChange={e=>setEmail(e.target.value)} type="email" required/></label><label><span>Password</span><input value={password} onChange={e=>setPassword(e.target.value)} type="password" required/></label><div className="login-options"><label className="remember"><input type="checkbox"/> Remember me</label><button type="button">Forgot password?</button></div>{error&&<div className="error">{error}</div>}<button className="primary-btn"><span>Enter Drishti</span><span>→</span></button><div className="demo-account"><span className="demo-account-label">Demo workspace</span><div className="demo-role-options" role="group" aria-label="Demo account role">{['Customer','Investigator','Admin'].map(role=><button type="button" key={role} className={demoRole===role?'active':''} onClick={()=>{setDemoRole(role);setEmail(`${role.toLowerCase()}@demo.com`);setPassword('Demo@123')}}>{role}</button>)}</div></div></form>
			</div>
		</section>
		<section className="platform-section" id="platform"><div className="section-heading"><div><span>01 / PLATFORM</span><h2>Clarity at every<br/>point of decision.</h2></div><p>Built for claim teams that need the complete picture without slowing down.</p></div><div className="feature-grid"><article><span className="feature-index">01</span><div className="feature-icon"><Eye/></div><h3>Visual intelligence</h3><p>Spot inconsistencies across claims, documents, locations and timelines.</p><a href="#intelligence">Explore <b>↗</b></a></article><article><span className="feature-index">02</span><div className="feature-icon">⌁</div><h3>Risk orchestration</h3><p>Prioritize investigation queues using transparent, evidence-led risk signals.</p><a href="#intelligence">Explore <b>↗</b></a></article><article><span className="feature-index">03</span><div className="feature-icon">◎</div><h3>Decision trace</h3><p>Keep every note, document and decision connected in one secure timeline.</p><a href="#security">Explore <b>↗</b></a></article></div></section>
		<section className="intelligence-section" id="intelligence"><div className="signal-panel"><div className="signal-header"><span>LIVE SIGNAL MONITOR</span><b><i/> SYSTEM ACTIVE</b></div><div className="signal-graph"><div className="signal-y"><span>100</span><span>75</span><span>50</span><span>25</span><span>0</span></div><svg viewBox="0 0 620 220" preserveAspectRatio="none"><defs><linearGradient id="signalFill" x1="0" y1="0" x2="0" y2="1"><stop stopColor="#d9ff63" stopOpacity=".28"/><stop offset="1" stopColor="#d9ff63" stopOpacity="0"/></linearGradient></defs><path className="signal-area" d="M0 184 C70 176 86 128 145 145 C205 162 220 64 288 95 C342 120 365 44 420 70 C480 96 500 32 620 48 L620 220 L0 220Z" fill="url(#signalFill)"/><path className="signal-line" d="M0 184 C70 176 86 128 145 145 C205 162 220 64 288 95 C342 120 365 44 420 70 C480 96 500 32 620 48" fill="none" stroke="#d9ff63" strokeWidth="3"/></svg></div><div className="signal-footer"><span>Claims analyzed</span><strong>12,840</strong><span>Signals identified</span><strong>184</strong></div></div><div className="intelligence-copy"><span>02 / INTELLIGENCE</span><h2>See the pattern.<br/><em>Know the risk.</em></h2><p>Move beyond isolated records. Drishti connects evidence to reveal emerging patterns, repeat behavior and unusual claim activity.</p><ul><li><b>01</b><span>Cross-claim pattern analysis</span></li><li><b>02</b><span>Explainable risk factors</span></li><li><b>03</b><span>Human-led final decision</span></li></ul></div></section>
	</main>
	<footer className="landing-footer" id="security">
		<div className="footer-main">
			<div className="footer-brand">
				<a className="landing-brand" href="#top"><BrandMark small/><span><strong>DRISHTI</strong><small>INSURANCE INTELLIGENCE</small></span></a>
				<p>Drishti makes complex insurance intelligence visible, explainable and secure across every claim journey.</p>
				<div className="footer-socials" aria-label="Social links"><a href="#top" aria-label="LinkedIn">in</a><a href="#top" aria-label="X">X</a><a href="#top" aria-label="YouTube">▶</a><a href="#top" aria-label="Instagram">◎</a></div>
				<div className="footer-security"><span>See every claim clearly.</span><b><ShieldAlert/> DRISHTI SECURED</b></div>
			</div>
			<div className="footer-columns">
				<div><span>Platform</span><a href="#platform">Visual Intelligence</a><a href="#platform">Doubt Engine</a><a href="#intelligence">DPAI Scanner</a><a href="#intelligence">API Security</a><a href="#intelligence">Risk Partnership</a><a href="#intelligence">Mobile Platform</a></div>
				<div><span>Company</span><a href="#top">About Drishti</a><a href="#top">Careers</a><a href="#intelligence">Customers</a><a href="#security">Partners</a><a href="#top">Contact Us</a><a href="#top">Webinars</a></div>
				<div><span>Resources</span><a href="#security">Trust Center</a><a href="#intelligence">Live Platform</a><a href="#intelligence">Security Courses</a><a href="#top">Articles</a><a href="#security">Help Articles</a><a href="#security">System Status</a></div>
				<div><span>Legal</span><a href="#security">Privacy Policy</a><a href="#security">Terms of Service</a><a href="#security">Security Policy</a></div>
			</div>
		</div>
		<div className="footer-bottom"><a className="footer-mark" href="#top"><BrandMark small/></a><span>Copyright © 2026 Drishti Intelligence</span><div><a href="#top">Privacy Policy</a><a href="#top">Terms of Service</a><a href="#top">Report a Vulnerability</a></div></div>
	</footer>
</div>}

function Shell({title,children}:{title:string;children:any}){
	const [dark,setDark]=useState(false); const [open,setOpen]=useState(true); const [notifications,setNotifications]=useState(false);
	const user=JSON.parse(localStorage.getItem('user')||'{}'); const nav=useNavigate(); const location=useLocation(); const role=user.role;
	const links=role==='Customer'?[['Overview','/customer',LayoutDashboard,'Claims and policy summary'],['Submit Claim','/customer/submit',Plus,'Start a new claim'],['My Claims','/customer/claims',FileText,'Track claim progress'],['Policies','/customer/policies',WalletCards,'Review active coverage'],['Documents','/customer/documents',FileText,'Manage claim documents'],['Payments','/customer/payments',WalletCards,'View settlements'],['Claim Timeline','/customer/timeline',ClipboardCheck,'Follow claim updates'],['Support','/customer/support',Users,'Help and guidance']]:role==='Admin'?[['Overview','/admin',LayoutDashboard,'Administration summary'],['User Management','/admin/users',Users,'Manage platform users'],['Policies','/admin/policies',WalletCards,'Manage coverage and terms'],['Providers','/admin/providers',Building2,'Manage provider network'],['Claims Control','/admin/claims',ClipboardCheck,'Monitor all claim activity'],['Analytics','/admin/analytics',BarChart3,'Platform performance'],['Security Center','/admin/security',ShieldAlert,'Access and audit control'],['System Health','/admin/system',Eye,'Monitor platform status']]:[
		['Overview','/investigator',LayoutDashboard,'Claims and risk summary'],
		['Priority Queue','/investigator/priority',ClipboardCheck,'Highest-risk claims first'],
		['Evidence Workspace','/investigator/evidence',FileText,'Review claim documents'],
		['SLA & Deadlines','/investigator/sla',ClipboardCheck,'Track review deadlines'],
		['Team Workload','/investigator/team',Users,'Balance investigator capacity'],
		['Activity Log','/investigator/activity',BarChart3,'Review recent actions'],
		['Relationship Network','/investigator/network',Users,'Map claim, customer and provider links'],
		['Evidence Intelligence','/investigator/intelligence',Eye,'Detect evidence anomalies'],
		['Analytics','/investigator/analytics',ShieldAlert,'Risk and case analytics']];
	function logout(){localStorage.clear();nav('/login')}
	return <div className={`${dark?'app app-dark':'app'} ${role==='Investigator'?'investigator-workspace':''} ${role==='Investigator'?(dark?'investigator-dark':'investigator-light'):''} ${role==='Customer'?'customer-workspace':''} ${role==='Customer'?(dark?'customer-dark':'customer-light'):''} ${role==='Admin'?'admin-workspace':''}`}>
		<aside className={open?'sidebar':'sidebar collapsed'}>
			<div className="side-brand"><BrandMark small/> {open&&<strong>DRISHTI</strong>}</div>
			<nav>{links.map(([name,path,Icon,description]:any)=><button key={name} className={location.pathname===path?'active':''} onClick={()=>nav(path)}><Icon/><span><b>{name}</b>{open&&<small>{description}</small>}</span></button>)}</nav>
			<button className="collapse" onClick={()=>setOpen(!open)}>«</button>
		</aside>
		<div className="main"><header><div className="search"><Search/><input placeholder="Search claims, customers, policy numbers..."/></div><div className="header-actions">
			<button onClick={()=>setDark(!dark)} title={dark?'Switch to light mode':'Switch to dark mode'}>{dark?<Sun/>:<Moon/>}</button>
			<div className="notification-wrap"><button className="notification" title="Notifications" onClick={()=>setNotifications(!notifications)}><Bell/><i/></button>{notifications&&<div className="notification-panel"><div className="notification-head"><b>Notifications</b><button onClick={()=>setNotifications(false)}>×</button></div><div className="notification-item unread"><i/><span><b>High-risk claim needs review</b><small>CLM-1024 · 4 minutes ago</small></span></div><div className="notification-item"><i/><span><b>Evidence upload completed</b><small>CLM-1026 · 18 minutes ago</small></span></div><div className="notification-item"><i/><span><b>Decision awaiting approval</b><small>CLM-1025 · 1 hour ago</small></span></div></div>}</div>
			<div className="avatar">{user.name?.[0]||'U'}</div><div className="profile"><b>{user.name}</b><small>{role}</small></div><button className="logout" title="Logout" onClick={logout}><LogOut/></button>
		</div></header>
		<main><div className="page-title"><div><span className="eyebrow">DRISHTI WORKSPACE</span><h1>{title}</h1></div></div>{children}</main><footer className="workspace-footer"><span>Drishti Intelligence</span><span>Secure operations environment</span></footer></div>
	</div>
}

function Stat({label,value,color}:{label:string;value:string|number;color:string}){return <div className="stat"><div style={{background:color}}><ShieldAlert/></div><div><small>{label}</small><strong>{value}</strong></div></div>}

function ClaimTable({claims,onSelect}:{claims:Claim[];onSelect?: (c:Claim)=>void}){const [query,setQuery]=useState('');const [risk,setRisk]=useState('ALL');const filtered=claims.filter(c=>(risk==='ALL'||c.risk_category===risk)&&(`${c.claim_id} ${c.customer} ${c.type}`.toLowerCase().includes(query.toLowerCase())));
return <div className="card table-card"><div className="card-head"><div><h3>Claims</h3><p>{filtered.length} records</p></div><div className="table-tools"><div className="mini-search"><Search/><input placeholder="Search" value={query} onChange={e=>setQuery(e.target.value)}/></div><select value={risk} onChange={e=>setRisk(e.target.value)}><option>ALL</option><option>HIGH</option><option>MEDIUM</option><option>LOW</option></select></div></div><div className="table-wrap"><table><thead><tr><th>Claim ID</th><th>Customer</th><th>Category</th><th>Amount</th><th>Risk</th><th>Status</th></tr></thead><tbody>{filtered.map(c=><tr key={c.id} onClick={()=>onSelect?.(c)} className={onSelect?'clickable':''}><td><b>{c.claim_id}</b></td><td>{c.customer}</td><td>{c.type}</td><td>₹{Number(c.amount).toLocaleString('en-IN')}</td><td><span className={`risk ${c.risk_category.toLowerCase()}`}>{c.risk_score} · {c.risk_category}</span></td><td><span className="status">{c.status}</span></td></tr>)}</tbody></table></div></div>}

function InvestigatorOverview(){const [claims,setClaims]=useState<Claim[]>([]);const [selected,setSelected]=useState<Claim|null>(null);const [detail,setDetail]=useState<any>(null);const [risk,setRisk]=useState<any>(null);const [note,setNote]=useState('');const [toast,setToast]=useState('');
useEffect(()=>{api.get('/claims').then(r=>setClaims(r.data.claims)).catch(()=>setClaims([]))},[]);
async function openClaim(c:Claim){setSelected(c);const [d,r]=await Promise.all([api.get(`/claims/${c.id}`),api.post(`/claims/${c.id}/risk`)]);setDetail(d.data.claim);setRisk(r.data)}
async function decide(decision:string){if(!selected)return;const reason=note;if(decision!=='APPROVED'&&!reason){setToast('A reason is required');return}await api.post(`/claims/${selected.id}/decision`,{decision,reason});if(note)await api.post(`/claims/${selected.id}/notes`,{note});setToast(`Claim ${decision.toLowerCase()} recorded`);setSelected(null);const r=await api.get('/claims');setClaims(r.data.claims)}
const high=claims.filter(c=>c.risk_category==='HIGH').length;const pending=claims.filter(c=>c.status==='SUBMITTED'||c.status==='INVESTIGATION').length;
return <Shell title="Claim Investigation"><div className="stats"><Stat label="Total claims" value={claims.length} color="#2563eb"/><Stat label="Pending reviews" value={pending} color="#f59e0b"/><Stat label="High-risk claims" value={high} color="#ef4444"/><Stat label="Low-risk claims" value={claims.filter(c=>c.risk_category==='LOW').length} color="#10b981"/></div>
	<div className="investigator-insights">
		<section className="card priority-queue"><div className="card-head"><div><h3>Priority review queue</h3><p>Sorted by risk and urgency</p></div><button className="inv-icon-btn">•••</button></div><div className="priority-list">{[...claims].sort((a,b)=>b.risk_score-a.risk_score).slice(0,4).map((c,i)=><button key={c.id} className="priority-row" onClick={()=>openClaim(c)}><span className="priority-rank">0{i+1}</span><div><b>{c.claim_id}</b><small>{c.customer} · {c.type}</small></div><span className={`risk ${c.risk_category.toLowerCase()}`}>{c.risk_score}</span></button>)}</div></section>
		<section className="card risk-intelligence"><div className="card-head"><div><h3>Risk intelligence</h3><p>Portfolio risk distribution</p></div><span className="live-pill"><i/>LIVE</span></div><div className="risk-donut"><div><strong>{high}</strong><span>High risk</span></div></div><div className="risk-bars"><div><span>Low</span><b><i style={{width:`${claims.filter(c=>c.risk_category==='LOW').length/Math.max(claims.length,1)*100}%`}}/></b></div><div><span>Medium</span><b><i style={{width:`${claims.filter(c=>c.risk_category==='MEDIUM').length/Math.max(claims.length,1)*100}%`}}/></b></div><div><span>High</span><b><i style={{width:`${claims.length?high/claims.length*100:0}%`}}/></b></div></div></section>
		<section className="card sla-watch"><div className="card-head"><div><h3>SLA watch</h3><p>Review deadlines</p></div><span className="sla-count">{pending} active</span></div><div className="sla-ring"><div><strong>{pending}</strong><span>Due soon</span></div></div><div className="sla-meta"><span>Average review</span><b>18h 42m</b></div></section>
	</div>
	<div className="investigator-grid-bottom"><section className="card activity-panel"><div className="card-head"><div><h3>Live activity</h3><p>Recent investigation events</p></div><button className="outline-btn">View all</button></div><div className="activity-list"><div><i/><span><b>Risk scan completed</b><small>CLM-1026 · Just now</small></span></div><div><i/><span><b>Evidence uploaded</b><small>CLM-1024 · 12 minutes ago</small></span></div><div><i/><span><b>Decision recorded</b><small>CLM-1025 · 38 minutes ago</small></span></div><div><i/><span><b>Investigation assigned</b><small>Team Alpha · 1 hour ago</small></span></div></div></section>
	<section className="card workload-panel"><div className="card-head"><div><h3>Investigator workload</h3><p>Active case distribution</p></div></div><div className="workload-bars"><div><span>Demo Investigator</span><b><i style={{width:'72%'}}/></b><strong>72%</strong></div><div><span>Team Alpha</span><b><i style={{width:'48%'}}/></b><strong>48%</strong></div><div><span>Team Core</span><b><i style={{width:'31%'}}/></b><strong>31%</strong></div></div></section></div>
	<ClaimTable claims={claims} onSelect={openClaim}/>{toast&&<div className="toast">{toast}<button onClick={()=>setToast('')}><X/></button></div>}{selected&&<div className="modal-backdrop" onMouseDown={()=>setSelected(null)}><div className="modal investigation-modal" onMouseDown={e=>e.stopPropagation()}><div className="modal-head"><div><span className="eyebrow">CLAIM INVESTIGATION</span><h2>{selected.claim_id}</h2></div><button onClick={()=>setSelected(null)}><X/></button></div><div className="investigation-grid"><section><h3>Claim overview</h3><dl><dt>Customer</dt><dd>{detail?.customer}</dd><dt>Category</dt><dd>{detail?.type}</dd><dt>Amount</dt><dd>₹{Number(selected.amount).toLocaleString('en-IN')}</dd><dt>Location</dt><dd>{detail?.location}</dd></dl></section><section><h3>Fraud risk</h3><div className="risk-score"><b>{risk?.score||0}</b><span>/100 · {risk?.category}</span></div>{risk?.factors?.map((f:any)=><details key={f.code}><summary>{f.title} <b>+{f.contribution}</b></summary><p>{f.reason}</p></details>)}</section></div><label>Investigation note<textarea value={note} onChange={e=>setNote(e.target.value)} placeholder="Document findings and evidence..."/></label><div className="decision-actions"><button className="approve" onClick={()=>decide('APPROVED')}><CheckCircle/>Approve</button><button className="investigate" onClick={()=>decide('INVESTIGATION')}>Investigate further</button><button className="reject" onClick={()=>decide('REJECTED')}><XCircle/>Reject</button></div></div></div>}</Shell>}

function Customer(){const [claims,setClaims]=useState<Claim[]>([]);const [show,setShow]=useState(false);const [toast,setToast]=useState('');const [form,setForm]=useState<any>({claim_type:'Motor Accident',policy_number:'',incident_date:'',incident_time:'',location:'',amount:'',description:'',provider:''});const [file,setFile]=useState<File|null>(null);
useEffect(()=>{api.get('/claims').then(r=>setClaims(r.data.claims)).catch(()=>setClaims([]))},[]);
async function submit(e:FormEvent){e.preventDefault();try{const r=await api.post('/claims',form);if(file){const fd=new FormData();fd.append('file',file);await api.post(`/claims/${r.data.claim.id}/documents`,fd)}setToast(`Claim ${r.data.claim.claim_id} submitted`);setShow(false);const c=await api.get('/claims');setClaims(c.data.claims)}catch(err:any){setToast(err.response?.data?.message||'Unable to submit claim')}}
return <Shell title="Customer Dashboard"><div className="page-title action-row"><span></span><button className="primary-btn" onClick={()=>setShow(true)}><Plus/>Submit new claim</button></div><div className="stats"><Stat label="Total claims" value={claims.length} color="#2563eb"/><Stat label="Under review" value={claims.filter(c=>c.status==='INVESTIGATION'||c.status==='SUBMITTED').length} color="#f59e0b"/><Stat label="Approved" value={claims.filter(c=>c.status==='APPROVED').length} color="#10b981"/><Stat label="Rejected" value={claims.filter(c=>c.status==='REJECTED').length} color="#ef4444"/></div><ClaimTable claims={claims}/>{toast&&<div className="toast">{toast}<button onClick={()=>setToast('')}><X/></button></div>}{show&&<div className="modal-backdrop" onMouseDown={()=>setShow(false)}><form className="modal claim-modal" onSubmit={submit} onMouseDown={e=>e.stopPropagation()}><div className="modal-head"><div><span className="eyebrow">NEW CLAIM</span><h2>Submit claim</h2></div><button type="button" onClick={()=>setShow(false)}><X/></button></div><div className="form-grid"><label>Claim type<select value={form.claim_type} onChange={e=>setForm({...form,claim_type:e.target.value})}><option>Motor Accident</option><option>Health</option><option>Property</option></select></label><label>Policy number<input value={form.policy_number} onChange={e=>setForm({...form,policy_number:e.target.value})} required/></label><label>Incident date<input type="date" value={form.incident_date} onChange={e=>setForm({...form,incident_date:e.target.value})} required/></label><label>Incident time<input type="time" value={form.incident_time} onChange={e=>setForm({...form,incident_time:e.target.value})}/></label><label>Location<input value={form.location} onChange={e=>setForm({...form,location:e.target.value})} required/></label><label>Claim amount<input type="number" value={form.amount} onChange={e=>setForm({...form,amount:e.target.value})} required/></label><label className="span2">Hospital / garage / provider<input value={form.provider} onChange={e=>setForm({...form,provider:e.target.value})}/></label><label className="span2">Incident description<textarea value={form.description} onChange={e=>setForm({...form,description:e.target.value})} required/></label><label className="span2 upload-label"><Upload/>Supporting document<input type="file" accept=".jpg,.jpeg,.png,.pdf" onChange={e=>setFile(e.target.files?.[0]||null)}/></label></div><button className="primary-btn submit-wide">Submit claim</button></form></div>}</Shell>}

function AdminPage(){const [tab,setTab]=useState('users');const [users,setUsers]=useState<any[]>([]);const [policies,setPolicies]=useState<any[]>([]);const [providers,setProviders]=useState<any[]>([]);const [analytics,setAnalytics]=useState<any>(null);
const {pathname}=useLocation();useEffect(()=>{Promise.all([api.get('/admin/users'),api.get('/admin/policies'),api.get('/admin/providers'),api.get('/analytics/overview'),api.get('/analytics/claims')]).then(([u,p,pr,a,c])=>{setUsers(u.data.users);setPolicies(p.data.policies);setProviders(pr.data.providers);setAnalytics({...a.data,claims:c.data})}).catch(()=>{})},[]);
useEffect(()=>{const section=pathname.split('/').pop();setTab(section as any)},[pathname]);async function toggle(u:any){await api.patch(`/admin/users/${u.id}`,{active:!u.active});setUsers(users.map(x=>x.id===u.id?{...x,active:!x.active}:x))}
return <Shell title="Administration"><div className="stats"><Stat label="Users" value={analytics?.users||users.length} color="#2563eb"/><Stat label="Policies" value={analytics?.policies||policies.length} color="#10b981"/><Stat label="Providers" value={analytics?.providers||providers.length} color="#8b5cf6"/><Stat label="Fraud alerts" value={analytics?.fraud_alerts||0} color="#ef4444"/></div><div className="admin-tabs"><button className={tab==='users'?'active':''} onClick={()=>setTab('users')}>Users</button><button className={tab==='policies'?'active':''} onClick={()=>setTab('policies')}>Policies</button><button className={tab==='providers'?'active':''} onClick={()=>setTab('providers')}>Providers</button><button className={tab==='analytics'?'active':''} onClick={()=>setTab('analytics')}>Analytics</button></div>{tab==='users'&&<div className="card table-card"><div className="table-wrap"><table><thead><tr><th>Name</th><th>Email</th><th>Role</th><th>Status</th><th>Action</th></tr></thead><tbody>{users.map(u=><tr key={u.id}><td><b>{u.name}</b></td><td>{u.email}</td><td>{u.role}</td><td>{u.active?'Active':'Inactive'}</td><td><button className="outline-btn" onClick={()=>toggle(u)}>{u.active?'Deactivate':'Activate'}</button></td></tr>)}</tbody></table></div></div>}{tab==='policies'&&<div className="card table-card"><div className="table-wrap"><table><thead><tr><th>Policy</th><th>Type</th><th>Coverage</th><th>Valid until</th></tr></thead><tbody>{policies.map(p=><tr key={p.id}><td><b>{p.policy_number}</b></td><td>{p.policy_type}</td><td>₹{Number(p.coverage_limit).toLocaleString('en-IN')}</td><td>{p.end_date}</td></tr>)}</tbody></table></div></div>}{tab==='providers'&&<div className="card table-card"><div className="table-wrap"><table><thead><tr><th>Provider</th><th>Type</th><th>Risk status</th></tr></thead><tbody>{providers.map(p=><tr key={p.id}><td><b>{p.name}</b></td><td>{p.provider_type}</td><td>{p.suspicious?'Suspicious':'Normal'}</td></tr>)}</tbody></table></div></div>}{tab==='analytics'&&analytics&&<div className="grid-2"><div className="card chart-card"><h3>Claims by month</h3><ResponsiveContainer width="100%" height={300}><BarChart data={analytics.claims.monthly}><CartesianGrid strokeDasharray="3 3"/><XAxis dataKey="month"/><YAxis/><Tooltip/><Bar dataKey="value" fill="#2563eb"/></BarChart></ResponsiveContainer></div><div className="card chart-card"><h3>Risk distribution</h3><ResponsiveContainer width="100%" height={300}><PieChart><Pie data={analytics.claims.risk} dataKey="value" nameKey="name" cx="50%" cy="50%" outerRadius={90}>{analytics.claims.risk.map((_:any,i:number)=><Cell key={i} fill={['#10b981','#f59e0b','#ef4444'][i%3]}/>)}</Pie><Tooltip/></PieChart></ResponsiveContainer></div></div>}</Shell>}

function CustomerPolicies(){const [policies,setPolicies]=useState<any[]>([]);useEffect(()=>{api.get('/policies').then(r=>setPolicies(r.data.policies)).catch(()=>setPolicies([]))},[]);return <Shell title="My Policies"><div className="card table-card"><div className="table-wrap"><table><thead><tr><th>Policy number</th><th>Type</th><th>Coverage limit</th><th>Valid until</th><th>Status</th></tr></thead><tbody>{policies.map(p=><tr key={p.id}><td><b>{p.policy_number}</b></td><td>{p.policy_type}</td><td>₹{Number(p.coverage_limit).toLocaleString('en-IN')}</td><td>{p.end_date||'-'}</td><td><span className="status">{p.active?'ACTIVE':'INACTIVE'}</span></td></tr>)}</tbody></table></div></div></Shell>}

function Protected({role,children}:{role:string;children:any}){const raw=localStorage.getItem('user');if(!raw)return <Navigate to="/login"/>;const u=JSON.parse(raw);return u.role===role?children:<Navigate to={u.role==='Customer'?'/customer':u.role==='Admin'?'/admin':'/investigator'}/>} 
export default function AppFunctional(){return <BrowserRouter><Routes><Route path="/login" element={<Login/>}/><Route path="/investigator" element={<Protected role="Investigator"><InvestigatorOverview/></Protected>}/><Route path="/investigator/priority" element={<Protected role="Investigator"><FeaturePage type="priority"/></Protected>}/><Route path="/investigator/evidence" element={<Protected role="Investigator"><FeaturePage type="evidence"/></Protected>}/><Route path="/investigator/sla" element={<Protected role="Investigator"><FeaturePage type="sla"/></Protected>}/><Route path="/investigator/team" element={<Protected role="Investigator"><FeaturePage type="team"/></Protected>}/><Route path="/investigator/activity" element={<Protected role="Investigator"><FeaturePage type="activity"/></Protected>}/><Route path="/investigator/network" element={<Protected role="Investigator"><FeaturePage type="network"/></Protected>}/><Route path="/investigator/intelligence" element={<Protected role="Investigator"><FeaturePage type="intelligence"/></Protected>}/><Route path="/investigator/analytics" element={<Protected role="Investigator"><FeaturePage type="analytics"/></Protected>}/><Route path="/investigator/:section" element={<Protected role="Investigator"><InvestigatorOverview/></Protected>}/><Route path="/customer" element={<Protected role="Customer"><Customer/></Protected>}/><Route path="/customer/submit" element={<Protected role="Customer"><CustomerFeaturePage type="submit"/></Protected>}/><Route path="/customer/claims" element={<Protected role="Customer"><CustomerFeaturePage type="claims"/></Protected>}/><Route path="/customer/policies" element={<Protected role="Customer"><CustomerFeaturePage type="policies"/></Protected>}/><Route path="/customer/documents" element={<Protected role="Customer"><CustomerFeaturePage type="documents"/></Protected>}/><Route path="/customer/payments" element={<Protected role="Customer"><CustomerFeaturePage type="payments"/></Protected>}/><Route path="/customer/timeline" element={<Protected role="Customer"><CustomerFeaturePage type="timeline"/></Protected>}/><Route path="/customer/support" element={<Protected role="Customer"><CustomerFeaturePage type="support"/></Protected>}/><Route path="/customer/legacy-claims" element={<Protected role="Customer"><Customer/></Protected>}/><Route path="/customer/policies" element={<Protected role="Customer"><CustomerPolicies/></Protected>}/><Route path="/customer/:section" element={<Protected role="Customer"><Customer/></Protected>}/><Route path="/policies" element={<Protected role="Customer"><CustomerPolicies/></Protected>}/><Route path="/admin" element={<Protected role="Admin"><AdminPage/></Protected>}/><Route path="/admin/users" element={<Protected role="Admin"><AdminFeaturePage type="users"/></Protected>}/><Route path="/admin/policies" element={<Protected role="Admin"><AdminFeaturePage type="policies"/></Protected>}/><Route path="/admin/providers" element={<Protected role="Admin"><AdminFeaturePage type="providers"/></Protected>}/><Route path="/admin/claims" element={<Protected role="Admin"><AdminFeaturePage type="claims"/></Protected>}/><Route path="/admin/analytics" element={<Protected role="Admin"><AdminFeaturePage type="analytics"/></Protected>}/><Route path="/admin/security" element={<Protected role="Admin"><AdminFeaturePage type="security"/></Protected>}/><Route path="/admin/system" element={<Protected role="Admin"><AdminFeaturePage type="system"/></Protected>}/><Route path="/admin/:section" element={<Protected role="Admin"><AdminPage/></Protected>}/><Route path="*" element={<Navigate to="/login"/>}/></Routes></BrowserRouter>}

function FeaturePage({type}:{type:string}){
	const [claims,setClaims]=useState<Claim[]>([]);
	useEffect(()=>{api.get('/claims').then(r=>setClaims(r.data.claims)).catch(()=>setClaims([]))},[]);
	const titles:any={priority:['Priority review queue','Claims ranked by urgency and fraud risk'],evidence:['Evidence workspace','Review documents, OCR results and claim attachments'],sla:['SLA & deadlines','Monitor pending reviews before deadlines expire'],team:['Team workload','Balance investigation capacity across teams'],activity:['Activity log','Review recent actions and case changes'],network:['Relationship network','Map hidden links across claims, customers and providers'],intelligence:['Evidence intelligence','Detect anomalies across documents and claim evidence'],analytics:['Risk analytics','Analyze claim volume, risk and investigation trends']};
	const [title,description]=titles[type]||titles.priority;
	return <Shell title={title}><div className="feature-description"><div><span>INVESTIGATOR TOOL</span><p>{description}</p></div><button className="outline-btn">Export report</button></div>
		{type==='priority'&&<div className="feature-layout"><ClaimTable claims={[...claims].sort((a,b)=>b.risk_score-a.risk_score)} /><section className="card feature-side"><div className="card-head"><div><h3>Queue health</h3><p>Current priority distribution</p></div></div><div className="feature-metric"><strong>{claims.filter(c=>c.risk_category==='HIGH').length}</strong><span>Critical claims</span></div><div className="feature-metric"><strong>{claims.filter(c=>c.status==='SUBMITTED').length}</strong><span>Awaiting triage</span></div></section></div>}
		{type==='evidence'&&<div className="feature-layout"><section className="card evidence-grid"><div className="card-head"><div><h3>Evidence library</h3><p>Documents linked to active claims</p></div></div>{claims.map(c=><div className="evidence-row" key={c.id}><div className="evidence-icon"><FileText/></div><div><b>{c.claim_id}</b><small>{c.customer} · {c.type}</small></div><span>OCR READY</span></div>)}</section><section className="card feature-side"><div className="card-head"><div><h3>Review checklist</h3><p>Evidence validation</p></div></div><label className="feature-check"><input type="checkbox"/> Identity verified</label><label className="feature-check"><input type="checkbox"/> Documents readable</label><label className="feature-check"><input type="checkbox"/> Timeline consistent</label></section></div>}
		{type==='sla'&&<div className="feature-layout"><section className="card sla-feature"><div className="card-head"><div><h3>Deadline watch</h3><p>Cases requiring timely action</p></div></div>{claims.map((c,i)=><div className="sla-row" key={c.id}><div><b>{c.claim_id}</b><small>{c.customer}</small></div><span className="sla-time">{i===0?'2h 18m':'8h 42m'}</span><div className="sla-progress"><i style={{width:`${70-i*16}%`}}/></div></div>)}</section><section className="card feature-side"><div className="feature-metric"><strong>{claims.filter(c=>c.status==='SUBMITTED'||c.status==='INVESTIGATION').length}</strong><span>Active deadlines</span></div></section></div>}
		{type==='team'&&<div className="feature-layout"><section className="card team-feature"><div className="card-head"><div><h3>Team capacity</h3><p>Current investigator assignments</p></div></div>{[['Demo Investigator',72],['Team Alpha',48],['Team Core',31]].map(([name,value]:any)=><div className="team-row" key={name}><div className="team-avatar">{String(name).charAt(0)}</div><div><b>{name}</b><small>{value}% capacity</small></div><div className="team-progress"><i style={{width:`${value}%`}}/></div></div>)}</section><section className="card feature-side"><div className="feature-metric"><strong>{claims.length}</strong><span>Cases distributed</span></div></section></div>}
		{type==='activity'&&<div className="feature-layout"><section className="card activity-feature"><div className="card-head"><div><h3>Recent activity</h3><p>Latest workspace events</p></div></div>{[['Risk scan completed','CLM-1026','Just now'],['Evidence uploaded','CLM-1024','12 minutes ago'],['Decision recorded','CLM-1025','38 minutes ago'],['Case assigned','Team Alpha','1 hour ago']].map(([titleText,ref,time]:any)=><div className="activity-row" key={titleText}><i/><div><b>{titleText}</b><small>{ref} · {time}</small></div></div>)}</section><section className="card feature-side"><div className="feature-metric"><strong>24</strong><span>Events today</span></div></section></div>}
		{type==='analytics'&&<div className="feature-layout"><section className="card analytics-feature"><div className="card-head"><div><h3>Risk analytics</h3><p>Claim risk overview</p></div></div><div className="analytics-bars">{claims.map(c=><div key={c.id}><span>{c.claim_id}</span><b><i style={{width:`${Math.min(c.risk_score,100)}%`}}/></b><strong>{c.risk_score}</strong></div>)}</div></section><section className="card feature-side"><div className="feature-metric"><strong>{claims.length?Math.round(claims.reduce((sum,c)=>sum+c.risk_score,0)/claims.length):0}</strong><span>Average risk score</span></div></section></div>}
		{type==='network'&&<div className="feature-layout"><section className="card network-feature"><div className="card-head"><div><h3>Claim relationship map</h3><p>Detected shared entities and connections</p></div><span className="live-pill"><i/> 4 clusters</span></div><div className="network-map"><div className="network-line line-a"/><div className="network-line line-b"/><div className="network-line line-c"/><div className="network-node node-center"><Eye/><b>Central claim</b></div><div className="network-node node-a"><b>Customer</b><small>3 claims</small></div><div className="network-node node-b"><b>Provider</b><small>High link</small></div><div className="network-node node-c"><b>Policy</b><small>Shared</small></div><div className="network-node node-d"><b>Address</b><small>2 matches</small></div></div></section><section className="card feature-side"><div className="card-head"><div><h3>Network signals</h3><p>Strongest associations</p></div></div><div className="network-signal"><span>Shared provider</span><b>High confidence</b></div><div className="network-signal"><span>Repeated address</span><b>Medium confidence</b></div><div className="network-signal"><span>Linked policy</span><b>Verified</b></div></section></div>}
		{type==='intelligence'&&<div className="feature-layout"><section className="card intelligence-feature"><div className="card-head"><div><h3>Evidence intelligence</h3><p>Cross-document anomaly scan</p></div><span className="live-pill"><i/> LIVE SCAN</span></div><div className="evidence-scan"><div className="scan-document"><FileText/><span/><span/><span/></div><div className="scan-result"><div><b>Identity mismatch</b><small>High confidence</small></div><div><b>Date inconsistency</b><small>Medium confidence</small></div><div><b>Duplicate image detected</b><small>Review required</small></div></div></div></section><section className="card feature-side"><div className="card-head"><div><h3>Scan summary</h3><p>Evidence anomalies</p></div></div><div className="feature-metric"><strong>3</strong><span>Flags detected</span></div><div className="feature-metric"><strong>82%</strong><span>Review confidence</span></div></section></div>}
	</Shell>
}

function CustomerFeaturePage({type}:{type:string}){
	const [claims,setClaims]=useState<Claim[]>([]);
	const [policies,setPolicies]=useState<any[]>([]);
	useEffect(()=>{Promise.all([api.get('/claims'),api.get('/policies')]).then(([c,p])=>{setClaims(c.data.claims||[]);setPolicies(p.data.policies||[])}).catch(()=>{})},[]);
	const titles:any={submit:['Submit a claim','Create a new insurance claim'],claims:['My claims','Track every claim and its current status'],policies:['My policies','Review coverage and policy details'],documents:['Document center','Manage claim documents and uploads'],payments:['Payments','View settlements and payment history'],timeline:['Claim timeline','Follow updates across claim activity'],support:['Customer support','Get help and manage support requests']};
	const [title,description]=titles[type]||titles.claims;
	return <Shell title={title}><div className="feature-description"><div><span>CUSTOMER WORKSPACE</span><p>{description}</p></div>{type==='submit'&&<button className="primary-btn">Start claim</button>}</div>
		{type==='submit'&&<div className="customer-feature-grid"><section className="card customer-action-card"><div className="customer-action-icon"><Plus/></div><div><h3>Submit a new claim</h3><p>Report an incident, attach evidence and receive a claim reference.</p></div><button className="primary-btn">Create claim</button></section><section className="card feature-side"><div className="card-head"><div><h3>Before you begin</h3><p>Recommended information</p></div></div><label className="feature-check"><input type="checkbox"/> Policy number ready</label><label className="feature-check"><input type="checkbox"/> Incident details available</label><label className="feature-check"><input type="checkbox"/> Supporting documents</label></section></div>}
		{type==='claims'&&<div className="feature-layout"><ClaimTable claims={claims}/><section className="card feature-side"><div className="card-head"><div><h3>Claim summary</h3><p>Current portfolio</p></div></div><div className="feature-metric"><strong>{claims.length}</strong><span>Total claims</span></div><div className="feature-metric"><strong>{claims.filter(c=>c.status==='APPROVED').length}</strong><span>Approved</span></div></section></div>}
		{type==='policies'&&<div className="customer-feature-grid">{policies.map(p=><section className="card customer-policy-card" key={p.id}><span className="policy-status">ACTIVE</span><h3>{p.policy_number}</h3><p>{p.policy_type}</p><div><span>Coverage</span><b>₹{Number(p.coverage_limit).toLocaleString('en-IN')}</b></div><button className="outline-btn">View policy</button></section>)}</div>}
		{type==='documents'&&<div className="feature-layout"><section className="card evidence-grid"><div className="card-head"><div><h3>Documents</h3><p>Claim and policy files</p></div></div>{claims.map(c=><div className="evidence-row" key={c.id}><div className="evidence-icon"><FileText/></div><div><b>{c.claim_id}</b><small>{c.customer} · {c.type}</small></div><span>AVAILABLE</span></div>)}</section><section className="card feature-side"><div className="card-head"><div><h3>Upload document</h3><p>Add supporting evidence</p></div></div><label className="customer-upload"><Upload/><span>Choose a file</span><input type="file"/></label></section></div>}
		{type==='payments'&&<div className="customer-feature-grid"><section className="card customer-payment-card"><div className="card-head"><div><h3>Settlement overview</h3><p>Payment and reimbursement status</p></div></div><div className="feature-metric"><strong>₹0</strong><span>Pending settlement</span></div><div className="feature-metric"><strong>{claims.filter(c=>c.status==='APPROVED').length}</strong><span>Approved claims</span></div></section><section className="card feature-side"><div className="card-head"><div><h3>Payment methods</h3><p>Bank and reimbursement</p></div></div><div className="payment-row"><b>Primary bank</b><small>Connected</small></div></section></div>}
		{type==='timeline'&&<div className="feature-layout"><section className="card activity-feature"><div className="card-head"><div><h3>Claim timeline</h3><p>Latest claim updates</p></div></div>{claims.map((c,i)=><div className="activity-row" key={c.id}><i/><div><b>{c.claim_id} · {c.status}</b><small>{c.type} · Update {i+1}</small></div></div>)}</section><section className="card feature-side"><div className="feature-metric"><strong>{claims.length}</strong><span>Timeline records</span></div></section></div>}
		{type==='support'&&<div className="customer-feature-grid"><section className="card customer-support-card"><div className="customer-action-icon"><Users/></div><h3>Contact support</h3><p>Get help with claims, policies or documents.</p><button className="primary-btn">Start request</button></section><section className="card feature-side"><div className="card-head"><div><h3>Helpful resources</h3><p>Common support topics</p></div></div><div className="support-link">Claim status</div><div className="support-link">Policy coverage</div><div className="support-link">Document upload</div></section></div>}
	</Shell>
}

function AdminFeaturePage({type}:{type:string}){
	const [users,setUsers]=useState<any[]>([]);const [policies,setPolicies]=useState<any[]>([]);const [providers,setProviders]=useState<any[]>([]);const [claims,setClaims]=useState<Claim[]>([]);
	useEffect(()=>{Promise.all([api.get('/admin/users'),api.get('/admin/policies'),api.get('/admin/providers'),api.get('/claims')]).then(([u,p,pr,c])=>{setUsers(u.data.users||[]);setPolicies(p.data.policies||[]);setProviders(pr.data.providers||[]);setClaims(c.data.claims||[])}).catch(()=>{})},[]);
	const titles:any={users:['User management','Control accounts, roles and access'],policies:['Policy management','Manage policy inventory and coverage'],providers:['Provider network','Monitor providers and network risk'],claims:['Claims control','Review platform-wide claim activity'],analytics:['Analytics center','Measure platform performance and trends'],security:['Security center','Audit access and security events'],system:['System health','Monitor service status and uptime']};
	const [title,description]=titles[type]||titles.users;
	return <Shell title={title}><div className="feature-description"><div><span>ADMINISTRATION TOOL</span><p>{description}</p></div><button className="outline-btn">Export report</button></div>
		{type==='users'&&<div className="feature-layout"><section className="card admin-feature-table"><div className="card-head"><div><h3>User directory</h3><p>{users.length} platform accounts</p></div></div><div className="table-wrap"><table><thead><tr><th>User</th><th>Email</th><th>Role</th><th>Status</th></tr></thead><tbody>{users.map(u=><tr key={u.id}><td><b>{u.name}</b></td><td>{u.email}</td><td>{u.role}</td><td><span className="status">{u.active?'ACTIVE':'INACTIVE'}</span></td></tr>)}</tbody></table></div></section><section className="card feature-side"><div className="feature-metric"><strong>{users.filter(u=>u.active).length}</strong><span>Active users</span></div><div className="feature-metric"><strong>{users.filter(u=>u.role==='Admin').length}</strong><span>Administrators</span></div></section></div>}
		{type==='policies'&&<div className="customer-feature-grid">{policies.map(p=><section className="card customer-policy-card" key={p.id}><span className="policy-status">ACTIVE</span><h3>{p.policy_number}</h3><p>{p.policy_type}</p><div><span>Coverage</span><b>₹{Number(p.coverage_limit).toLocaleString('en-IN')}</b></div><button className="outline-btn">Manage policy</button></section>)}</div>}
		{type==='providers'&&<div className="feature-layout"><section className="card evidence-grid"><div className="card-head"><div><h3>Provider network</h3><p>{providers.length} registered providers</p></div></div>{providers.map(p=><div className="evidence-row" key={p.id}><div className="evidence-icon"><Building2/></div><div><b>{p.name}</b><small>{p.provider_type}</small></div><span className={p.suspicious?'risk high':'risk low'}>{p.suspicious?'REVIEW':'NORMAL'}</span></div>)}</section><section className="card feature-side"><div className="feature-metric"><strong>{providers.filter(p=>p.suspicious).length}</strong><span>Flagged providers</span></div></section></div>}
		{type==='claims'&&<div className="feature-layout"><ClaimTable claims={claims}/><section className="card feature-side"><div className="feature-metric"><strong>{claims.length}</strong><span>Total claims</span></div><div className="feature-metric"><strong>{claims.filter(c=>c.status==='INVESTIGATION'||c.status==='SUBMITTED').length}</strong><span>Open claims</span></div></section></div>}
		{type==='analytics'&&<div className="feature-layout"><section className="card analytics-feature"><div className="card-head"><div><h3>Platform analytics</h3><p>Claims and policy performance</p></div></div><div className="analytics-bars">{claims.map(c=><div key={c.id}><span>{c.claim_id}</span><b><i style={{width:`${Math.min(c.risk_score,100)}%`}}/></b><strong>{c.risk_score}</strong></div>)}</div></section><section className="card feature-side"><div className="feature-metric"><strong>{policies.length}</strong><span>Policies</span></div><div className="feature-metric"><strong>{providers.length}</strong><span>Providers</span></div></section></div>}
		{type==='security'&&<div className="feature-layout"><section className="card activity-feature"><div className="card-head"><div><h3>Security events</h3><p>Recent access and audit activity</p></div></div>{[['Administrator login','Security','Just now'],['User role changed','Admin action','18 minutes ago'],['Policy updated','Audit record','1 hour ago'],['Access review completed','Security','Today']].map(([titleText,ref,time]:any)=><div className="activity-row" key={titleText}><i/><div><b>{titleText}</b><small>{ref} · {time}</small></div></div>)}</section><section className="card feature-side"><div className="feature-metric"><strong>Protected</strong><span>Security state</span></div></section></div>}
		{type==='system'&&<div className="feature-layout"><section className="card team-feature"><div className="card-head"><div><h3>System services</h3><p>Core platform availability</p></div></div>{[['API Gateway','Operational',96],['Database','Operational',99],['Document Processor','Operational',92],['Authentication','Operational',100]].map(([name,status,value]:any)=><div className="team-row" key={name}><div className="team-avatar">✓</div><div><b>{name}</b><small>{status}</small></div><div className="team-progress"><i style={{width:`${value}%`}}/></div></div>)}</section><section className="card feature-side"><div className="feature-metric"><strong>99.9%</strong><span>Uptime</span></div></section></div>}
	</Shell>
}








